from collections import defaultdict
pts=defaultdict(list)
for r,row in enumerate(a):
 for c,v in enumerate(row):
  if v!=3 and not (1<=r<=5 and 1<=c<=5) and not (1<=r<=5 and 7<=c<=11) and not (7<=r<=11 and 1<=c<=5) and not (7<=r<=11 and 7<=c<=11) and not (13<=r<=17 and 1<=c<=5) and not (13<=r<=17 and 7<=c<=11): pts[v].append((r,c))
for color,pos in pts.items():
 print(color, pos, 'bbox',(min(r for r,c in pos),max(r for r,c in pos),min(c for r,c in pos),max(c for r,c in pos)))

# Build cropped output: retain the swatch layout, invert each matching motif in its 3x3 center.
out=[row[:13] for row in a]
# bounding boxes of the small matching motifs, represented as (color, top, left)
motifs={
  8:(15,15), 6:(3,19), 9:(11,15), 4:(15,19), 7:(7,19), 1:(3,15)
}
# large block top-left positions, in matching color order
blocks={8:(1,1),6:(1,7),9:(7,1),4:(7,7),7:(13,1),1:(13,7)}
for color,(top,left) in motifs.items():
  for br,bc in [blocks[color]]:
    for dr in range(3):
      for dc in range(3):
        # If small motif has color at offset, carve that center position to background.
        if a[top+dr][left+dc]==color:
          out[br+1+dr][bc+1+dc]=3
# Print rows and interior patterns
print('\n'.join(' '.join(map(str,row)) for row in out))
print('dims',len(out),len(out[0]))
for color,(br,bc) in blocks.items():
 print(color,[[out[br+1+dr][bc+1+dc] for dc in range(3)] for dr in range(3)])
